-- Splynn Dimensional Market: 12 D-Squad, Kittani, Octurill, Kizh and miscellaneous arms, printed 162-164 and 170-172.
-- 12 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~361-splynn-arms.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('line-lockers', 'Line Lockers', 'rifts', 'weapon', 2, 250000, 'Not generally available; when it is, no less than 250,000 credits', '2D4 S.D.C.; no M.D.', 0, '200 feet (61 m), magically enhanced', 'One throw; the bola has to be fetched back before another', NULL, NULL, NULL, 50, 'A living bola: a parasitic organism that passes for the ordinary weapon apart from its organic feel. It is a mainstay of D-Squad because whoever it wraps is pinned to the ley line at the spot where it caught him, by a mechanism nobody fully understands. The victim stays rooted until the cords are unwound and dropped, which takes 1D4 melee actions, and a captive bound with them stays fixed to that place until he wriggles loose or someone frees him. It does not stop ley line phasing, so it does little against a Ley Line Walker. Weighs 2 or 3 lbs (0.9 or 1.4 kg). Strike bonuses come from W.P. and P.P. alone. Most D-Squad members carry two to four of them.', 'Rifts World Book 21: Splynn Dimensional Market p.162', NULL),
  ('time-lock', 'Time-Lock', 'rifts', 'weapon', 2, 1000000, 'Not generally available; when it is, no less than 1 million credits', '2D4 S.D.C.; no M.D.', 0, '200 feet (61 m), magically enhanced', 'One throw; the bola has to be fetched back before another', NULL, NULL, NULL, 50, 'A second living bola carried by D-Squad. Instead of drawing on a ley line it makes its own field, which scrambles temporal energy: anyone caught in it can barely use Temporal Magic or time travel, with the same effect as the Time Maelstrom spell (Rifts World Book 3: England). Other teleportation, magical or natural, is hampered less severely, at -25% to its accuracy and ability. Weighs 2 to 3 lbs (0.9 to 1.4 kg). Strike bonuses come from W.P. and P.P. alone. D-Squad also has Time-Locks made as handcuffs and shackles; the book gives that form no figures of its own.', 'Rifts World Book 21: Splynn Dimensional Market p.162', NULL),
  ('barrier-projectors', 'Barrier Projectors', 'rifts', 'weapon', 10, 750000, '750,000 to 1 million credits; seldom seen for open sale, mostly used by special Splugorth troops', NULL, 0, '300 feet (91.4 m); the bubble is 8 feet (2.4 m) across', 'Six shots; all six regenerate in 24 hours, or at once at a Stone Pyramid', 'Two shots per melee round', NULL, NULL, NULL, 'A heavy, awkward hand-held projector about the size of a short rifle, with a fat squat cylinder for a barrel and two handles where a grip and trigger would be. Triggered by thought, its beam closes the target inside an energy bubble of 120 M.D.C., and nobody inside can teleport, phase or open a mystic portal. That makes it the tool for beings who teleport on their own and for Phase Powers users, who cannot get through a magic barrier in any case. It is also used a great deal to hold the members of raiding parties who have no magic. It does no damage itself.', 'Rifts World Book 21: Splynn Dimensional Market p.162', NULL),
  ('kittani-plasma-chainsaw', 'Kittani Plasma Chainsaw', 'rifts', 'weapon', 10, 60000, NULL, '6D6 M.D.', 1, 'Close combat, 2.5 feet (0.76 m) reach', '60 minutes per E-clip; each activation counts as one minute', 'Equal to the user''s hand to hand attacks per melee', NULL, NULL, NULL, 'The Kittani take on the North American Juicer chainsaw: no toothed chain, but a plasma field circulating round the edge of the blade. Its heavy damage has made it a hit in the arenas, the Kittani robot arenas above all, and with Juicers (Maxi-Killers in particular) and Bio-Borgs. A user without a P.S. of 19 or more, or supernatural strength, is -2 to strike with it. With no spinning chain it lacks that drawback of the Juicer original.', 'Rifts World Book 21: Splynn Dimensional Market p.162-163', NULL),
  ('kittani-plasma-net', 'Kittani Plasma Net', 'rifts', 'weapon', 6, 75000, '75,000 credits; a recharge costs 1,000 credits', '1D6x10 M.D. per melee round while trapped; 1D6+2 M.D. swung as a whip', 1, '5 feet (1.5 m) as a whip; thrown 12 feet (3.6 m), or 20 feet (6 m) with supernatural P.S. or P.P. over 23, at -1 to strike per extra 5 feet (1.5 m)', '15 minutes on its internal power supply; each activation counts as one minute', 'Thrown once, then it must be recovered to throw again', NULL, NULL, 20, 'A net for finishing off a beaten or cornered foe: thrown over him, it burns him while he fights it, and its weighted edges pull together magnetically once he is inside. The panic of being caught in it makes getting out harder. Built for the gladiatorial arena, it also appeals to warriors and to bounty hunters who will bring a bounty in dead or alive. A captive with supernatural P.S. of 30 or less tears free in one melee round (15 seconds) and a stronger one in two melee actions; one of ordinary strength must hack his way out with weapons or spend 1D4+1 melee rounds working loose. A remote control lets the owner govern the plasma field and handle the net safely, and its handle is always safe to hold. The book prints its weight as 6 lbs (1.8 kg).', 'Rifts World Book 21: Splynn Dimensional Market p.163', NULL),
  ('kittani-plasma-whip', 'Kittani Plasma Whip', 'rifts', 'weapon', 3, 30000, NULL, '2D4 S.D.C. unenergized; 1D6 M.D. or 2D6 M.D. per lash energized', 1, 'Close combat, 8 feet (2.4 m) reach', '60 minutes per E-clip; each activation counts as one minute', 'Equal to the user''s hand to hand attacks per melee', NULL, NULL, NULL, 'A segmented steel whip whose magnetic field keeps a sheath of plasma close around it, made with slavers and gladiators in mind. The low setting drives M.D.C. creatures and slaves along; the high one is for runaways and killing. Arena crowds love it. It fires no energy bolts, unlike most Kittani plasma melee weapons.', 'Rifts World Book 21: Splynn Dimensional Market p.163', NULL),
  ('kittani-plasma-harness', 'Kittani Plasma Harness', 'rifts', 'weapon', 15, 3600000, '3.6 million credits; sale strictly controlled and few made each year, refused to anyone known or suspected to deal with vampires', '5D6 M.D. per touch or punch; 1D6x10 M.D. per melee attack while an opponent is entangled, embraced or held; anything flammable touching the field is incinerated', 1, '1 to 2 feet (.3 to .6 m) from the wearer''s body', '15 minutes per short E-clip, 60 minutes per long clip', 'Equal to the wearer''s hand to hand attacks', NULL, NULL, 60, 'A body harness that wraps the wearer in a burning plasma field. Kittani engineers never fixed its flaws: the magnetic field upsets communications gear and electronics (moot, since the plasma destroys nearly anything worn or carried), and it gives the wearer no protection from his own field, which does him 2D6 M.D. each melee round. Put on sale anyway, it sold hugely to beings immune to fire, such as Fire Eaters, Bursters, Fire Warlocks and Fire Dragons, along with plenty of demons and magical creatures, though all but the Burster lose whatever they carry. It can go over ordinary armor, burning that away at 2D6 M.D. a melee round. S.D.C. bullets and weapons and anything else flammable burn up on contact. Vampires are immune to the field as well, and it shields them from wood, silver and modest water: over a gallon (3.8 liters) does a tenth of normal damage, and washing one clean takes a small river. Magically enchanted wood, such as Ironwood or Millennium Tree weapons, survives the field and can still reach the heart. For that reason the Splugorth Lords restrict its sale. Mostly used in the arena.', 'Rifts World Book 21: Splynn Dimensional Market p.163-164', NULL),
  ('octurill-vibro-axe', 'Octurill Vibro-Axe', 'rifts', 'weapon', 5, 32000, '32,000 credits; refitting for a fingered hand triples the price and takes a month or more by special order', '3D6+4', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'An axe made by the Octurill, an other-dimensional race of intelligent octopoids whose fine Mega-Damage weapons turn up regularly in the Splynn market. It is shaped for a tentacle: anyone without a prehensile tentacle or tail is -3 to strike and parry with it. It can be refitted for a hand with fingers by special order, at three times the price and at least a month''s wait. The book''s damage line, under its Mega-Damage label, reads 3D6+4 with no unit printed; it is stored as printed. The stat block is on p.171; the Octurill introduction with the penalty and the refit is on p.170.', 'Rifts World Book 21: Splynn Dimensional Market p.170-171', NULL),
  ('octurill-charged-particle-ejector', 'Octurill Charged Particle Ejector', 'rifts', 'weapon', 14, 26000, '26,000 credits; refitting for a fingered hand triples the price and takes a month or more by special order', '1D4x10 per blast', 1, '3000 feet (914 m)', '20 blasts per E-clip', 'Single blasts only', NULL, NULL, NULL, 'A long gun made by the Octurill, the other-dimensional octopoid race whose high-grade Mega-Damage weapons are regulars in the Splynn market. Its grip is built for a tentacle: anyone without a prehensile tentacle or tail is -3 to strike and parry with it. It can be refitted for a hand with fingers by special order, at three times the price and at least a month''s wait. Its heading spells the maker Octuril, with one l; the row uses the spelling of the section it sits in. The damage line, under its Mega-Damage label, prints no unit. The stat block is on p.171; the Octurill introduction with the penalty and the refit is on p.170.', 'Rifts World Book 21: Splynn Dimensional Market p.170-171', NULL),
  ('kizh-plasma-pistol', 'Kizh Plasma Pistol', 'rifts', 'weapon', 6, 24000, NULL, '3D6+4 per quad-blast (plasma); 1D6 M.D. with the Vibro-Blade', 1, 'Plasma blast 450 feet (137 m)', '15 blasts per E-clip', 'Equal to the wielder''s number of attacks, for both weapon systems', NULL, NULL, NULL, 'A bulky but well-balanced Kizh sidearm, rounded on top, with four barrels above a jagged front of spikes and blades. The Kizh are a warlike, semi-aquatic humanoid people, raiders and copyists known for practical, frightening-looking weapons. The bladed front lets the shooter punch or slash with the gun, and a sonic field over the spines and blades makes it a Mega-Damage Vibro-Weapon. On the printed page the stat block stands apart from this description, beneath the pistol''s drawing.', 'Rifts World Book 21: Splynn Dimensional Market p.171', NULL),
  ('kizh-ion-rifle', 'Kizh Ion Rifle', 'rifts', 'weapon', 13, 44000, NULL, '4D6 per blast (ion beam); 2D6+2 M.D. with the Vibro-Axe', 1, '1,800 feet (548.6 m)', '25 blasts per E-clip', 'Standard for the ion beam (Modern Weapon Proficiencies, Rifts RPG); equal to the wielder''s attacks with the axe', NULL, NULL, NULL, 'The long-arm partner of the Kizh plasma pistol: the same bulky, balanced build, rounded on top, but its jagged front is a large curved blade the size of an axe head. Like the pistol''s, it is a Vibro-Blade, here meant for slashing and chopping. The Kizh are warlike semi-aquatic humanoid raiders who also copy and resell others'' designs. On the printed page the stat block stands apart from this description, beneath the rifle''s drawing.', 'Rifts World Book 21: Splynn Dimensional Market p.171', NULL),
  ('power-jaw-helmet', 'Power Jaw Helmet', 'rifts', 'weapon', 5, 35000, '35,000 credits; a special order styled to match existing armor costs 25% more', '2D4 M.D. per bite', 1, NULL, NULL, NULL, NULL, NULL, 60, 'A power armor helmet with a strong hinged jaw, giving humans and others with no natural Mega-Damage bite one to use in melee. Its maker is unknown, though it is often credited to the builder of the Titan power armors. Styles range from plain to demonic, all doing the same damage from the hydraulics and the vibro-field on the teeth, and a universal coupling at the neck lets it fit nearly any human-sized power armor. It cannot be added to a helmet already owned, but one styled to match an existing helmet or suit can be ordered for 25% more.', 'Rifts World Book 21: Splynn Dimensional Market p.172', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 12 gear rows are in' AS assertion, count(*) AS got, 12 AS want
  FROM gear WHERE slug IN ('line-lockers', 'time-lock', 'barrier-projectors', 'kittani-plasma-chainsaw', 'kittani-plasma-net', 'kittani-plasma-whip', 'kittani-plasma-harness', 'octurill-vibro-axe', 'octurill-charged-particle-ejector', 'kizh-plasma-pistol', 'kizh-ion-rifle', 'power-jaw-helmet') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~361-splynn-arms.sql');
